<?php
session_start();
if (!isset($_SESSION['logged_in']) || $_SESSION['logged_in'] !== true) { header('Location: login.php'); exit; }
require_once __DIR__ . '/../services/databaseConnect.php';
use MongoDB\BSON\ObjectId;

$id = $_GET['id'] ?? '';
$error = $_GET['error'] ?? '';
try { $materialId = new ObjectId($id); } catch (Throwable $exception) { header('Location: materials.php'); exit; }
$material = $materialsCollection->findOne(['_id' => $materialId]);
if (!$material) { header('Location: materials.php'); exit; }
$messages = ['empty_name' => 'Введіть назву матеріалу.', 'invalid_type' => 'Оберіть тип матеріалу.', 'invalid_parameter' => 'Кожен параметр має містити назву та хоча б одне значення.', 'unknown_error' => 'Матеріал не вдалося змінити. Спробуйте ще раз.'];
function editMaterialText($value): string { return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); }
?>
<!doctype html><html lang="uk"><head><meta charset="UTF-8" /><meta name="viewport" content="width=device-width, initial-scale=1.0" /><link rel="icon" href="src/mars-reklama.com.ua-favicon.ico" type="image/png" /><link rel="stylesheet" href="styles/form-style.css" /><link rel="stylesheet" href="styles/general-style.css" /><title>Редагування матеріалу</title>  <link rel="stylesheet" href="styles/responsive.css" />
</head>
<body><div class="main-header"><img src="src/logo.jpg" alt="mars-logo" id="header-logo" draggable="false" /><div class="header-right-corner"><p id="main-greetings">Вітаю, <?= editMaterialText($_SESSION['username']) ?>!</p></div></div>
<div class="main-body"><p class="page-title">РЕДАГУВАННЯ МАТЕРІАЛУ</p><form action="services/editMaterialProcess.php" method="post" id="material-form"><input type="hidden" name="id" value="<?= editMaterialText($id) ?>" />
<div class="form-row"><label class="form-element" for="materialName">Назва матеріалу</label><input type="text" name="materialName" class="text-input" id="materialName" value="<?= editMaterialText($material['name'] ?? '') ?>" required /></div>
<div class="form-row"><label class="form-element">Тип матеріалу</label><div class="radio-options"><label><input type="radio" name="materialType" value="roll" <?= ($material['type'] ?? '') === 'roll' ? 'checked' : '' ?> />Рулонний</label><label><input type="radio" name="materialType" value="sheet" <?= ($material['type'] ?? '') === 'sheet' ? 'checked' : '' ?> />Листовий</label></div></div>
<div class="form-row"><label class="form-element">Додаткові поля</label><div id="custom-fields-container"><?php foreach (($material['parameters'] ?? []) as $parameter): ?><div class="custom-field-row"><div class="custom-field-cols-container"><div class="custom-field-cols-element"><p class="form-element">Параметр</p><input class="text-input custom-field-name" value="<?= editMaterialText($parameter['name'] ?? '') ?>" placeholder="Назва поля" /></div><div class="custom-field-cols-element values-column"><p class="form-element">Значення</p><div class="custom-field-values"><?php foreach (($parameter['values'] ?? []) as $value): ?><div class="custom-field-value-row"><input class="text-input custom-field-value" value="<?= editMaterialText($value) ?>" placeholder="Значення" /><button type="button" class="remove-custom-field-value" aria-label="Видалити значення">×</button></div><?php endforeach; ?></div><button type="button" class="add-custom-field-value">+ Додати значення</button></div><div class="custom-field-cols-element"><button type="button" class="remove-custom-field" aria-label="Видалити параметр">×</button></div></div></div><?php endforeach; ?></div><button type="button" id="add-custom-field" class="add-custom-field-button">+ Додати поле</button></div>
<div class="form-buttons"><input type="submit" value="Змінити" class="submit-button" /><button type="button" id="cancel-button">Скасувати</button></div></form></div>
<?php if (isset($messages[$error])): ?><script>alert(<?= json_encode($messages[$error]) ?>); history.replaceState({}, document.title, location.pathname);</script><?php endif; ?>
<script>
const fields=document.getElementById('custom-fields-container'),form=document.getElementById('material-form');
function valueInput(){const row=document.createElement('div');row.className='custom-field-value-row';row.innerHTML='<input class="text-input custom-field-value" placeholder="Значення" /><button type="button" class="remove-custom-field-value" aria-label="Видалити значення">×</button>';return row;}
function fieldRow(){const row=document.createElement('div');row.className='custom-field-row';row.innerHTML='<div class="custom-field-cols-container"><div class="custom-field-cols-element"><p class="form-element">Параметр</p><input class="text-input custom-field-name" placeholder="Назва поля" /></div><div class="custom-field-cols-element values-column"><p class="form-element">Значення</p><div class="custom-field-values"></div><button type="button" class="add-custom-field-value">+ Додати значення</button></div><div class="custom-field-cols-element"><button type="button" class="remove-custom-field" aria-label="Видалити параметр">×</button></div></div>';row.querySelector('.custom-field-values').appendChild(valueInput());return row;}
if(!fields.children.length)fields.appendChild(fieldRow());document.getElementById('add-custom-field').onclick=()=>fields.appendChild(fieldRow());fields.onclick=event=>{if(event.target.classList.contains('remove-custom-field'))event.target.closest('.custom-field-row').remove();if(event.target.classList.contains('add-custom-field-value'))event.target.closest('.custom-field-row').querySelector('.custom-field-values').appendChild(valueInput());if(event.target.classList.contains('remove-custom-field-value'))event.target.closest('.custom-field-value-row').remove();};form.addEventListener('submit',()=>fields.querySelectorAll('.custom-field-row').forEach((row,index)=>{row.querySelector('.custom-field-name').name=`customFieldName[${index}]`;row.querySelectorAll('.custom-field-value').forEach(input=>input.name=`customFieldValue[${index}][]`);}));document.getElementById('header-logo').onclick=()=>location.href='main.php';document.getElementById('cancel-button').onclick=()=>location.href='materials.php';
</script>  <script src="scripts/chat-notifications.js" defer></script>
</body></html>
